// Internal context wiring the parts together. Not part of the public API.
type MessageScrollerContextValue = {
  handleContentChange: () => void
  handleResize: () => void
  observeVisibility: () => void
  preserveScrollOnPrependRef: Octane.RefObject<boolean>
